vec4 effect(vec2 uv) {
  vec2 px = 1.0 / resolution; float r = 1.0 + amount * 14.0; vec4 acc = vec4(0.0); float n = 0.0;
  for (int i = -4; i <= 4; i++) for (int j = -4; j <= 4; j++) { vec2 o = vec2(float(i), float(j)) * r * 0.5 * px; float w = exp(-float(i*i + j*j) / 18.0); acc += getColor(uv + o) * w; n += w; }
  return acc / n;
}

vec4 effect(vec2 uv) {
  vec2 px = 1.0 / resolution; vec4 c = getColor(uv);
  vec4 s = getColor(uv + vec2(px.x, 0.0)) + getColor(uv - vec2(px.x, 0.0)) + getColor(uv + vec2(0.0, px.y)) + getColor(uv - vec2(0.0, px.y));
  return vec4(clamp(c.rgb + (c.rgb * 4.0 - s.rgb) * amount * 1.5, 0.0, 1.0), c.a);
}

vec4 effect(vec2 uv) {
