vec3 hue(vec3 c, float a) { const vec3 k = vec3(0.57735); float ca = cos(a); return c * ca + cross(k, c) * sin(a) + k * dot(k, c) * (1.0 - ca); }
vec4 effect(vec2 uv) {
  vec4 c = getColor(uv);
  return vec4(clamp(hue(c.rgb, time * (1.0 + amount * 4.0) + uv.y * amount * 3.0), 0.0, 1.0), c.a);
}

